"""Regression coverage for the behavior specified in SPEC.md."""

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    events = [{"converted": flag} for flag in (True, None, False)]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([{"converted": None}]) == 0.0


def test_conversion_rate_empty():
    rate = conversion_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    rate = pooled_conversion_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([], 0, 0), ([], 3, 0), ([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4),
     ([1, 2, 4], 2, 6), ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_flags_and_whitespace():
    events = parse_session_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t"])
    assert events == [session("a", 1, True), session("b", -2, False), session("c", 3, None)]
    assert events[0]["converted"] is True
    assert events[1]["converted"] is False
    assert events[2]["converted"] is None


def test_parse_session_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", " \t# not,a,session", "a,2,1", "\n"]
    assert parse_session_log(iter(lines)) == [session("a", 2, True)]
    assert parse_session_log([]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,not-a-day,1", "a,1.5,0", "a,,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["", " # comment", " \t", "valid,1,0", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_id_and_sorts():
    events = [
        session("z", 9, True),
        session("b", 2, False),
        session("a", 2, True),
        session("z", 1, False),
        session("b", 2, True),
    ]
    assert dedupe_sessions(events) == [events[3], events[2], events[4]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_zero_filled_and_bounded():
    events = [
        session("before", 0, True),
        session("first", 1, True),
        session("false", 2, False),
        session("unknown", 2, None),
        session("last1", 4, True),
        session("last2", 4, True),
        session("after", 5, True),
    ]
    assert daily_conversion_counts(events, 1, 4) == [1, 0, 0, 2]
    assert daily_conversion_counts(events, 4, 4) == [2]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


def test_campaign_summary_pooled_rounded_rate_and_nonempty_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 2, False), session("c", 3, None)],
        "empty": [],
    }
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 2), (3, 2), (5, 3), (20, 3)])
def test_campaign_summary_recent_uses_calendar_days(days, recent):
    groups = {"g": [session("a", 1, True), session("b", 4, True),
                    session("c", 4, True), session("d", 5, False)]}
    assert campaign_summary(groups, days) == {"rate": 0.75, "recent": recent, "groups": 1}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 7) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}, {"converted": False}],
        "empty": [],
        "a": [{"converted": True}, {"converted": None}],
        "best": [{"converted": True}],
        "zero": [{"converted": False}],
    }
    assert top_converting_groups(groups, 3) == ["best", "a", "z"]
    assert top_converting_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({"empty": []}, 1) == []
    assert top_converting_groups({}, 1) == []


def test_conversion_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [{"converted": None}],
              "a": [{"converted": True}, {"converted": False}]}
    rates = conversion_rate_by_group(groups)
    assert rates == {"a": 0.5, "b": 0.0, "z": None}
    assert list(rates) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 0, 2, 3, 0, 4], 2),
     ([1, -1, 2], 1), ([0, 1, 2, 3], 3)],
)
def test_longest_conversion_streak_positive_consecutive_entries(counts, expected):
    assert longest_conversion_streak(counts) == expected

